pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testRegression_property() public {
        address user = address(0x1234);
        vm.deal(user, 10 ether);

        vm.prank(user);
        c.Deposit{value: 1 ether}();

        // balances after deposit: user = 1 ether
        vm.prank(user);
        c.CashOut(0.5 ether);

        // reference: balance should be 0.5 ether (1 - 0.5)
