        address userB = address(0x456);
        vm.deal(userA, 1 ether);
        vm.deal(userB, 2 ether);
        vm.prank(userA);
        c.Deposit{value: 1 ether}();
        vm.prank(userB);
        c.Deposit{value: 2 ether}();
        vm.prank(userB);
        c.CashOut(1 ether);
        // After this, reference: userB balance = 2 - 1 = 1 ether
        // Buggy: userB balance = 2 + 1 = 3 ether
        uint256 balance = c.balances(userB);
        assertTrue(balance == 1 ether, "Balance should be 1 ether after CashOut");
    }
}

